package com.example.inventory;import com.example.inventory.dao.Database;import com.example.inventory.services.InventoryService;import com.example.inventory.ui.InventoryController;import javafx.application.Application;import javafx.scene.Scene;import javafx.stage.Stage;public class MainApp extends Application{private InventoryService s;public void start(Stage stage)throws Exception{Database.initializeDatabase();s=new InventoryService(Database.connect());stage.setTitle("Inventory Management System"); stage.setMinWidth(1000); stage.setMinHeight(680);Scene scene = new Scene(new InventoryController(s).createView(), 1150, 760); scene.getStylesheets().add(getClass().getResource("/styles.css").toExternalForm()); stage.setScene(scene);stage.show();}public void stop()throws Exception{if(s!=null)s.close();}public static void main(String[]a){launch(a);}}